      "title": "交通工具的绿色化：飞机、火车与汽车",
      "difficulty": 2,
      "passage": "<p><b>The greening of planes, trains and automobiles</b></p><p>Moving goods and people around the world is responsible for a large part of global CO2 <w>emissions</w> (排放). As the world races to <w>decarbonize</w> everything, it faces particular problems with transportation — which <w>accounts for</w> about a quarter of our energy-related greenhouse gas emissions. Here's the <w>breakdown</w> of the emissions in 2018 for different modes of transport.</p><p><i>（此处为 2018 年各类交通方式排放占比图表，原图见试卷 PDF。官方解析引用了其中两项数据：ROAD (PASSENGER) 45.1%、ROAD (GOODS) 29.4%。）</i></p><p>The fuels for transport need to be not just green, cheap and powerful, but also lightweight and safe enough to be carried around. Each mode of transport has its specific fuel needs. Much is still to be settled, but here are some of the solutions to get us going green.</p><p><b>PLANES — Synthetic hydrocarbons</b><br>The hardest sector to decarbonize is <w>aviation</w>. One long-term option for <w>sustainable</w> fuel for planes is to make <w>hydrocarbons</w> from recycled air.</p><p><b>CARS — Batteries</b><br>Batteries are energy-efficient and electric cars can plug into existing systems and services. New <w>solid-state</w> batteries will take a car farther on a single charge.</p><p><b>TRAINS — Electricity</b><br>Some trains are already <w>electrified</w> through rails or wires; others can be made electric in pretty simple ways.</p><p><b>TRUCKS — Hydrogen fuel cells</b><br>Hydrogen fuel cells are a lighter choice than batteries for trucks, but making green <w>hydrogen</w> is expensive.</p><p><b>SHIPS — Liquid ammonia</b><br>Liquid <w>ammonia</w> is easy to keep and transport, but it is hard to <w>ignite</w> (点燃) and requires an engine redesign.</p><p>This energy <w>transition</w> (变革) is global, and the amount of <w>renewable</w> energy the world will need is \"a little bit <w>mind-blowing</w>,\" says mechanical engineer Keith Wipke at the National Renewable Energy Laboratory. It's estimated that the global demand for electricity could more than double by 2050. Fortunately, analyses suggest that renewables are up to the task. \"We need to speed up the development of green energy, and it will all get used,\" says Wipke.</p>",
      "passageCn": "图表给出 2018 年各交通方式碳排放占比，再讲飞机汽车火车卡车轮船怎么走绿色燃料。",
