          "ans": "C",
          "locate": "图表 ROAD 部分两条数据：ROAD (PASSENGER) 45.1%、ROAD (GOODS) 29.4%。",
          "how": "这是图表加法题，不是找一个数就完事。题干问的是 road vehicles（道路车辆）整体占多少，而图上道路这一栏被拆成两条：客运 45.1%、货运 29.4%。客车和货车都属于道路车辆，所以要把两条加起来，45.1+29.4=74.5，选 C。B 就是专门给「只瞄了第一条数据就下笔」的人准备的坑；A、D 则是拿图上别的分项单列、或者多加了一项凑出来的数——题目只问道路，别把航空、航运也算进去。记住一个套路：图表题只要选项里出现某个分项的原始数字，八成就是在等你漏加。看到分类图，先数清题目问的是哪几类，再动加法。"
