          "locate": "TRAINS — Electricity 栏：Some trains are already electrified through rails or wires; others can be made electric in pretty simple ways.",
          "how": "题干里的关键词是 comparatively easily（相对容易），所以要去五个板块里找「说得最轻松」的那一段。火车那栏写：有些已经通过轨道或电线电气化了，其余的也能用 pretty simple ways（相当简单的方式）改成电动——simple 就是 easily 的同义替换，答案锁死 C。反过来看另外三个：飞机那栏第一句就说 the hardest sector（最难的领域），A 直接出局；卡车要用氢燃料电池但 making green hydrogen is expensive（贵），B 出局；轮船的液氨 hard to ignite 还要重新设计发动机，D 出局。这种「哪个最容易/最难」的题，其实是在考你能不能扫到 hardest、expensive、simple 这些评价词。"
