          "kind": "细节理解 · 2.5分",
          "q": "Who are the people mentioned at the beginning of paragraph 1?<div class=\"opts\"><span>A. Ninth graders.</span><span>B. Students' parents.</span><span>C. Modern writers.</span><span>D. Fictional characters.</span></div>",
          "ans": "D",
          "locate": "第1段第2句：More than once, I found myself wondering just how my students, who'd created these people, knew their subjects so well.",
          "how": "第一段先说「我遇到了一个拯救小镇的牛仔、一个逼儿子门门拿 A 的严父、一个现代版朱丽叶」，光看这句你可能真以为老师认识这些人。关键在紧接着的第二句：my students, who'd created these people——学生「创造」出来的人。既然是被创造出来的，那就是虚构人物，选 D。A 九年级学生指的是写文章的人，不是文章里的人；B 家长虽然出现了（严父、朱丽叶的父母），但那也是故事里的；C 现代作家更没影。这道题考的是「代词回指」：看到 these people 一定要往前回扫它指的是谁，别停在第一句就作答。"
