          "kind": "推理判断 · 2.5分",
          "q": "Why did the students perform poorly in writing their first essay?<div class=\"opts\"><span>A. They were not given enough time.</span><span>B. They had a very limited vocabulary.</span><span>C. They misunderstood the question.</span><span>D. They had little interest in the topic.</span></div>",
          "ans": "D",
          "locate": "第2段：Then I realized that the problem was the question itself. … writing, in and of itself, simply didn't strike them as important.",
          "how": "第一篇作文写砸了，老师自己给了原因：问题出在题目本身——「他们本可以就电脑的必要性写上好几页，但写作本身根本没让他们觉得重要」。没觉得重要、写不动，翻译成选项就是对这个话题没兴趣，选 D。C 最有迷惑性：老师说 the problem was the question itself，但那是「题目选得不对」，不是学生「看错题目」，两回事。A 时间不够、B 词汇量小，全文没有半个字提到，属于自己脑补。做原因题的顺序是：先找作者有没有直接说「原因」（realized/because/the problem was），有就照抄逻辑，别自己推。"
