          "q": "What does the underlined word \"staggering\" in paragraph 3 mean?<div class=\"opts\"><span>A. Mixed.</span><span>B. Amazing.</span><span>C. Similar.</span><span>D. Disturbing.</span></div>",
          "ans": "B",
          "locate": "第3段划线词紧接的下一句：The students took on diverse topics and turned in stories, 10 to 20 pages each, with characters that broadened my view and touched my heart.",
          "how": "猜词题永远看紧挨着的上下文，别查记忆里的词典。The results were staggering. 下一句立刻解释了「结果」是什么：学生选题多样，每篇交上来 10 到 20 页，人物拓宽了我的视野、打动了我的心。再对比第二段「大多数不到一页」——从不到一页到二十页，这是一个让人吃惊的好结果。所以 staggering 是褒义的「惊人的」，选 B Amazing。A 好坏参半、D 令人不安都是负面，跟 touched my heart 的语气对不上；C 相似跟 diverse（多样）正好相反。口诀：破折号、冒号、下一句的举例，就是出题人埋的免费词典。"
