          "ans": "A",
          "locate": "最后一段：I walked into class believing that writing is important as a means of communication. However, my students demonstrated something more important to me.",
          "how": "主旨题看最后一段的转折。作者说：我走进教室时以为写作重要是因为它能交流，然而学生向我展示了更重要的东西——写作能连接人、让我们换位思考、教我们怎样做人。注意这里的身份反转：老师是去教的，结果自己被教了，这不就是「教学相长」吗，选 A。B 大智若愚、C 知识就是力量、D 熟能生巧，都是听起来很正的谚语，但全文没有任何一条线索支撑（作者从没说学生练得多所以写得好，他说的是题目换了、兴趣来了）。谚语型主旨题的做法：先用一句话概括全文「谁在什么事上有了什么转变」，再拿这句话去套四个谚语，套得上的只有一个。"
