      "type": "七选五（记叙文·人物特写）",
      "title": "An Unsung Hero：咖啡馆里的无名英雄",
      "difficulty": 3,
      "passage": "<p><b>An <w>Unsung</w> Hero</b></p><p>Need a break between classes or just a quick <w>pick-me-up</w> in the morning? The College Cafe has just that, and more. _____36_____</p><p>Catherine Murphy, a cafe worker in a green shirt and black hat, makes sure that each customer gets exactly what they order. She goes back and forth between machines to make the drinks. _____37_____ As the customer grabs the drink from her hand, she smiles and says, \"Hello, how is your day?\" Even when the line is getting longer, she doesn't let it <w>get in the way of</w> her <w>genuine</w> conversations.</p><p>Murphy gets up at <w>a quarter to five</w> and drives thirty minutes every day to get to work on time. _____38_____ \"I do so because I like to make coffee for the students. I know they need it in the morning,\" Murphy said. Being a mother and wife has helped her become the woman she is. She believes she is here to serve.</p><p>One thing Murphy may not know is that her smile is <w>contagious</w> (有感染力) and can be the difference in a student having a much better day than they were having before seeing her. Joanna Wright, a senior political science <w>major</w>, loves coffee and goes to the cafe at least six days a week. _____39_____ \"Catherine always has a huge smile on her face, which always puts me in a cheerful mood,\" Wright said.</p><p>\"I enjoy working in the cafe,\" Murphy said. _____40_____ She has every <w>intention</w> of staying and continuing doing what she loves.</p>",
      "passageCn": "写大学咖啡馆员工凯瑟琳·墨菲十七年如一日，用真诚的服务和笑容温暖学生的故事。",
