          "no": "第48题",
          "kind": "名词词义辨析 · 1分",
          "q": "___48___<div class=\"opts\"><span>A. warning</span><span>B. request</span><span>C. description</span><span>D. reply</span></div>",
          "ans": "C",
          "locate": "空后冒号引出的原话：\"I hate this vase. Maybe you won't.\"",
          "how": "空后是个冒号加一句话：「我讨厌这个花瓶。也许你不会。」这是作者重新挂帖时自己写的文案，也就是商品说明，description（描述），选 C。这里要看清说话人是谁：这句话出自卖家之口，不是买家。D reply 回复就错在方向——回复是买家发给她的；A 警告，语气上像玩笑不像警告，而且没人会警告别人别拿免费花瓶；B 请求也不对，她没求人做任何事。冒号后面的内容就是空格的同位解释，读懂那句话的「体裁」，空格自然就有了。"
