      "passage": "<p>An exhibition at the Jiushi Art Museum in Shanghai is featuring artwork inspired by Go, or weiqi in Chinese, ____56____ <w>originated</w> in China more than 4,000 years ago.</p><p>Go is one of ____57____ earliest <w>binary-based</w> (基于二元的) games. The movements of the black and white pieces reflect the basic ideas of Eastern philosophy, according to Tu Ningning, who is in charge of the exhibition.</p><p>\"The exhibition brings together Go culture, cutting-edge technology and <w>contemporary</w> art,\" says Tu. \"We hope ____58____ (present) the rather abstract Go game and AI in a visual context, and <w>initiate</w> dialogues with <w>minimalist</w> art, <w>conceptual</w> art and <w>expressionism</w>.\"</p><p>\"In a Go game, each move should serve a long-term goal. You try to lead the <w>opponent</w> into your trap and force them to follow your '____59____ (guide)' till they lose,\" explains Wang Wei, a Go player among the visitors to the exhibition.</p><p>\"The players' personalities ____60____ (reveal) during the game, and one's weaknesses are exposed to the opponent,\" she adds. \"A <w>decent</w> winner always ____61____ (try) to beat the opponent ____62____ no more than one or two points as a <w>gesture</w> (姿态) of respect for the other side.\"</p><p>Tu says that the balance between the black and white pieces, the beauty in the ____63____ (strategy) <w>placement</w> of the pieces, ____64____ the energy flow following each move inspired artists to create oil paintings, <w>sculptures</w>, ____65____ (digital) generated pictures and <w>silk-screen prints</w> for the exhibition.</p>",
      "passageCn": "介绍上海一场以围棋为灵感的展览，把围棋文化、前沿科技与当代艺术放在一起对话。",
