          "ans": "B",
          "locate": "空前：I don't trust my laptop's spellchecker. 空后：Of course, these days there are plenty of online dictionaries and thesauruses, but I'm old-fashioned enough to prefer a hard cover…",
          "how": "空前作者甩了一句态度：我不信任电脑的拼写检查。这种「我不信任 X」后面几乎必然跟一句「为什么不信」。B 说 It takes no account of the context——它不考虑上下文，It 指代 spellchecker，正好给出理由：拼写检查只认单词对不对，不管你在这个语境里该用哪个词。选它还有个好处：解释完电子工具的短板，下一句转去讲「虽然有很多在线词典，但我还是偏爱纸质书」，逻辑顺滑。C 的 them 是复数，前一句只有单数的 spellchecker，代词数对不上，先排除。做 37 这种题记住两条：一看代词单复数能不能接上，二看空前是不是抛出了一个需要理由的判断。"
