          "no": "第38题",
          "kind": "上下文衔接 · 2.5分",
          "q": "____38____ 处应填入的最佳选项是？（选项见本块 options）",
          "ans": "E",
          "locate": "空后：It should give you a precise definition of each word, thus differentiating it from other words whose meanings are similar, but not identical. It will also usually show how the word is pronounced.",
          "how": "这个空在段首，段首句的活儿是「领起本段话题」，所以要往后看而不是往前看。空后连着两句都在讲词典还能干什么：给精确释义、区分近义词、标发音——全都不是拼写。E 说 Of course, a dictionary is not only for spelling（词典不只是用来拼写的），一个 not only 就把「除了拼写还有别的功能」这个话题挑起来了，后面两句正是在补 not only 之后的内容，而且 E 里的 a dictionary 正好是后两句 It 的先行词。G 也提到词典，但 G 说词典给的信息「不够」，是负面评价，跟后面列举一堆好处的正面语气拧着来。段首空的口诀：找一个能被后文全部句子共同支撑的话题句。"
