          "q": "____39____ 处应填入的最佳选项是？（选项见本块 options）",
          "ans": "A",
          "locate": "空前：It contains around 163,000 words, plus word combinations and idiomatic phrases. 空后：However, if I need to check the origin of a word or to look up examples of its usage, there's nothing better.",
          "how": "关键信号是空后的 However。有 However，就说明空里那句和它后面那句是相反的两面。空后是正面的：查词源、查用法例句时「没有比它更好的」。那空里必须是负面的、说这本词典的「不足」或「用得少」。A 说 I don't often use this dictionary（我不常用这本词典），负面，且 this dictionary 正好指本段开头那套两卷本 Shorter Oxford Dictionary，代词接得上。连起来读就是：这本大部头我平时不常翻，不过一旦要查词源和例句，它无敌。逻辑漂亮。做题习惯：先在原文里把 However/But/Yet 圈出来，转折词两边的「正负号」必须相反。"
