          "locate": "空前：“To make dictionaries is dull (乏味) work,” wrote Johnson, illustrating one definition of “dull”. 空后：A few minutes spent casting your eye over a page or two can be a rewarding experience.",
          "how": "空前引用 Johnson 的话：编词典是件乏味的活儿——负面。空后：随便翻上一两页几分钟，是件很有收获的事——正面。一负一正夹着这个空，中间那句必须是把语气扳过来的转折句。D 说 But a dictionary can be a pleasure to read（但词典读起来可以是一种乐趣），But 完成转折，pleasure 又和空后的 rewarding experience 呼应，同时还形成一个对比：编词典 dull，读词典 pleasure，两个动作对着写，特别工整。这也是全文的收尾立意。剩下的 C、G 两个是干扰项，做完记得回读一遍全篇，五句填进去应该像原本就长在那儿一样。"
