  "writingGuide": {
    "examNote": "五年写作考情：应用文（15分）里四年是「给外教或朋友写邮件」——2022 邀请外教做访谈、2023 对口语分组提建议、2024 分享美术课经历、2025 为英语报栏目二选一并说理由，只有 2021 是校刊投稿短文。读后续写（25分）五年全勤。结论：邮件三段式往死里练，续写背熟一套「动作+情感」写法。",
    "tasks": [
      {
        "year": 2025,
        "task": "给外教 Jenny 写邮件：为班级英语报新栏目在两个名字里选一个并说明理由"
      },
      {
        "year": 2024,
        "task": "给英国朋友 Chris 写邮件：分享上周在公园上美术课的经历"
      },
      {
        "year": 2023,
        "task": "给外教 Ryan 写邮件：对「随机两人一组练口语」提出看法和建议"
      },
      {
        "year": 2022,
        "task": "给外教 Caroline 写邮件：邀请她参加校广播站英语节目访谈"
      },
      {
        "year": 2021,
        "task": "向校英文报 Youth 投稿短文：庆祝创刊十周年"
      }
    ],
    "genres": [
      {
        "id": "applied",
        "name": "应用文（邮件三段式）",
        "tag": "主战场",
        "when": "15分 · 词数80左右 · 目标：12分钟写完，格式分一分不丢",
        "intro": "高考应用文＝换着题目考同一封信。三段式骨架从来不变：为什么写 → 把要求逐条写完 → 礼貌收尾。下面用 2022 年真题（邀请外教做访谈）把三段跑一遍。",
        "steps": [
          {
            "name": "第①段 · 开门见山（1-2句）",
            "how": "一句话说清你是谁、为什么写这封信——别寒暄半天。",
            "demo": "Dear Caroline, I'm Li Hua, head of the English program \"Talk and Talk\" at our school radio station. I'm writing to invite you to an interview."
          },
          {
            "name": "第②段 · 逐条回应题目要求（3-4句）",
            "how": "题目里「内容包括：1…2…」就是这段的提纲——一条写一两句，用 Also / Besides 串起来，写完对着题目逐条打勾。",
            "demo": "Our program shares campus stories with students every Friday. The interview is planned for next Wednesday afternoon, and we would love to hear your ideas about learning English."
          },
          {
            "name": "第③段 · 礼貌收尾（1-2句）",
            "how": "期待回复或表示感谢，然后落款——落款永远是 Yours, Li Hua。",
            "demo": "It would be great if you could join us. Looking forward to your reply. Yours, Li Hua"
          }
        ],
        "rules": [
          "先定时态再动笔：邀请/建议用将来时，分享经历用过去时——时态错是最亏的扣分。",
          "题目每条要求都要回应，漏一条降一档。",
          "词数 80 左右就好，写到 120 不加分只加错。",
          "格式三件套（称呼、正文分段、落款）是白给的分，一个不能丢。"
        ],
        "bank": [
          "I'm writing to tell you / invite you / ask for…（万能开头）",
          "I would appreciate it if you could…（礼貌请求）",
          "Looking forward to your reply.（万能结尾）",
          "It would be great if…（提议）",
          "Thanks for reading my letter.（收尾感谢）"
        ]
      },
      {
        "id": "cont",
        "name": "读后续写（两段150词）",
        "tag": "拉分题",
        "when": "25分 · 给一篇故事+两个段首句，续写两段 · 五年全勤",
        "intro": "续写不是自由发挥，是「戴着镣铐讲完故事」：情节顺着段首句走，语言用「动作+情感」交替。四步法：",
        "steps": [
          {
            "name": "第①步 · 读原文圈三样",
            "how": "人物关系、没解决的冲突、反复出现的物品——反复出现的东西（一块奖牌、一句话）后文十有八九要用来收尾。",
            "demo": "例：故事讲男孩害怕越野赛，反复出现「爸爸的鼓励」——续写就该让这句鼓励在关键时刻再响一次。"
          },
          {
            "name": "第②步 · 用段首句定情节",
            "how": "第一段的段首句一般是「事情起变化」，第二段一般是「问题解决+情感落点」。动笔前各用一句中文把两段要发生什么说清楚。",
            "demo": "例：段首句「I looked at David walking to the starting line…」→ 这段写他中途遇到困难但坚持完赛。"
          },
          {
            "name": "第③步 · 动作+情感交替写",
            "how": "一句具体动作（用准动词），跟一句心理或表情——整段都在「想」会很空，整段都在「跑」会很干。",
            "demo": "My legs were shaking, but I took a deep breath and stepped forward. The fear suddenly melted away."
          },
          {
            "name": "第④步 · 结尾回扣原文",
            "how": "用第①步圈出的「反复出现的物品/话」收尾，让两段像原作者写的。",
            "demo": "Holding the medal, I finally understood what Dad meant: the finish line belongs to those who dare to start."
          }
        ],
        "rules": [
          "不加新人物、不换地点、不开新冲突——只把旧冲突解决掉。",
          "每段 75 词左右，两段合计 150 上下。",
          "背三个高级句型直接套：Hearing this, …（分词开头）／…, which made me realize…（定语从句）／It was … that …（强调句）。"
        ]
      }
    ]
  },
